/* From Uiverse.io by Nawsome - Tags: loader */
.__UIV_SCOPE__ .circle {
  animation: move571 4s linear infinite;
}

.__UIV_SCOPE__ .circle.right {
  animation-direction: reverse;
}

@keyframes move571 {
  25% {
    transform: translateX(-32px);
  }

  75% {
    transform: translateX(32px);
  }
}
